do $$declare s text;begin s:=pg_get_functiondef('prospecting.personalization_api(text,jsonb)'::regprocedure);s:=replace(s,$x$elsif a='suppression_sync' or a='_suppression_sync' then$x$,$x$elsif a in('suppression_sync','_suppression_sync','_campaign_suppression_sync') then$x$);s:=replace(s,$x$if length(coalesce(d->>'source',''))<10 or d->>'complete' is distinct from 'true' then$x$,$x$if length(coalesce(d->>'source',''))<10 or (a<>'_campaign_suppression_sync' and d->>'complete' is distinct from 'true') then$x$);s:=replace(s,$x$update prospecting.personalization_settings set suppression_checked_at=now(),suppression_source=d->>'source' where id;$x$,$x$if a<>'_campaign_suppression_sync' then update prospecting.personalization_settings set suppression_checked_at=now(),suppression_source=d->>'source' where id;end if;$x$);execute s;end$$;
